#!/usr/bin/env python3
"""Summarize independently checked objectives and solver proof bounds."""
import hashlib, html, importlib.util, json, math, pathlib
import highspy
ROOT=pathlib.Path(__file__).resolve().parents[2];OUT=ROOT/'docs/optimality-2026-10-11'
spec=importlib.util.spec_from_file_location('bench',ROOT/'harness/tools/optimality-bench.py');b=importlib.util.module_from_spec(spec);spec.loader.exec_module(b)
def num(x):return '—' if x is None else f'{x:,.6f}'.rstrip('0').rstrip('.')
def main():
 data=json.loads((OUT/'results.json').read_text());scip={r['file']:r for r in json.loads((OUT/'scip.json').read_text())} if (OUT/'scip.json').exists() else {}
 records=[]
 for r in data['records']:
  h=highspy.Highs();h.setOptionValue('output_flag',False);h.readModel(str(ROOT/r['file']));model=b.o.model_json(h.getLp());sign=model['sense'];types=list(map(str,h.getLp().integrality_))
  # Repair the first run's reference check for semi-variable zero domains.
  if any('Semi' in t for t in types) and not (r['highs'].get('check') or {}).get('feasible'):
   h.setOptionValue('time_limit',120.0);h.setOptionValue('threads',8);h.run();sol=h.getSolution()
   if sol.value_valid:r['highs']['check']=b.domain_check(model,list(sol.col_value),types)
  candidates=[];bounds=[];statuses=[]
  for name,s,check,supported in [('Optio',r['optio'],r['check'],r['optioSupportsVariableTypes']),('HiGHS',r['highs'],r['highs'].get('check'),True),('SCIP',scip.get(r['file'],{}),scip.get(r['file'],{}).get('check'),True)]:
   if not s:continue
   status=str(s.get('status',s.get('statusCode')));statuses.append((name,status))
   valid=bool(supported and check and check.get('feasible'))
   if valid and s.get('objective') is not None:candidates.append((sign*s['objective'],name,s['objective'],status))
   if supported and s.get('dualBound') is not None and not any(v in status for v in ['kInfeasible','kUnbounded','infeasible','unbounded']):bounds.append((sign*s['dualBound'],name,s['dualBound']))
  best=min(candidates) if candidates else None;bound=max(bounds) if bounds else None
  obj=best[2] if best else None;dual=bound[2] if bound else None
  gap=max(0,sign*(obj-dual)) if obj is not None and dual is not None else None
  tol=1e-7*(1+abs(obj)) if obj is not None else 0
  conflict=bool(obj is not None and dual is not None and sign*(dual-obj)>tol)
  claimed_optimal=any(s=='7' or s.endswith('.kOptimal') or s=='optimal' for _,_,_,s in candidates)
  optimal=bool(best and bound and gap<=tol and not conflict and claimed_optimal)
  infeasible=any('kInfeasible' in s or s=='infeasible' for _,s in statuses)
  unbounded=any(s.endswith('.kUnbounded') or s=='unbounded' for _,s in statuses)
  status='Bound conflict' if conflict else 'Optimal' if optimal else 'Infeasible' if infeasible else 'Unbounded' if unbounded else 'Open'
  record={'file':r['file'],'sha256':hashlib.sha256((ROOT/r['file']).read_bytes()).hexdigest(),'sense':'min' if sign>0 else 'max','objective':obj,'bound':dual,'boundSource':bound[1] if bound else None,'objectiveSource':best[1] if best else None,'absoluteGap':gap,'relativeGap':gap/max(1e-10,abs(obj)) if gap is not None else None,'status':status,'solverStatuses':dict(statuses)}
  records.append(record)
 (OUT/'bounds.json').write_text(json.dumps(records,indent=2,allow_nan=False)+'\n')
 (ROOT/'harness/fixtures/certified-bounds.json').write_text(json.dumps({'method':'Native numerical solver bounds, independent primal feasibility checks; 120 seconds per solver, eight threads. Bound is a lower bound for minimization and an upper bound for maximization. File hashes bind results to these exact fixtures.','records':records},indent=2,allow_nan=False)+'\n')
 counts={k:sum(r['status']==k for r in records) for k in ['Optimal','Infeasible','Unbounded','Open','Bound conflict']}
 lines=['# Sudoku performance and full-suite optimality — 2026-10-11','',f"All {len(records)} fixtures were attempted. Results: {counts['Optimal']} optimal, {counts['Infeasible']} infeasible, {counts['Unbounded']} unbounded, {counts['Open']} open, {counts['Bound conflict']} bound conflicts.",'','## Method','','Release Optio with the `parallel` feature and eight workers; native HiGHS 1.15.1 with eight configured threads. Each solver gets 120 seconds per fixture and zero requested absolute/relative MIP gap. HiGHS receives an independently checked Optio incumbent when available. Remaining cases receive a SCIP 10 concurrent portfolio with eight workers and a 120-second budget (including its one-second Optio seed). Solver benchmark runs are sequential; brief compilation and validation overlapped some runs. Final Sudoku medians were measured with other solver work stopped. Each two-minute problem/solver measurement is a single run. The first eight fixtures preceded the row-multiplier projection refinement; their valid bounds and reference proofs are retained, with the original native build hash in `build.json`. Subsequent records carry their native build hash. Parsing, process startup, and independent checking are excluded from solver times. Deadlines are checked cooperatively and can overshoot slightly. These are numerical solver proofs, not exact rational proof certificates. Bounds use the objective in the original model sense; maximization has an upper bound.','', 'Optio now propagates unit-coefficient binary cardinality rows, returning fully fixed models without simplex. It computes LP Lagrangian bounds from unperturbed costs and bounds rather than using the primal LP objective; branch pruning and the reported global bound use these values. Open or numerically unresolved nodes cannot certify optimality. An exhausted search with a material remaining dual gap returns a feasible-solution status.','', '## Sudoku A/B','','Medians of nine measured solves after two warmups, same new build with presolve disabled/enabled. Every solution is independently checked. The final timing pass ran after the full solver suite finished, without competing solver work. HiGHS was measured in the same runtimes, also with nine samples after two warmups. Native HiGHS used eight configured threads; WASM is single-threaded. The WASM reference comparison is restricted to Sudoku, whose zero-cost feasible solutions are trivially optimal.','','| Fixture | Runtime | Presolve off (ms) | Presolve on (ms) | Speedup | HiGHS (ms) |','|---|---|---:|---:|---:|---:|']
 sudoku=json.loads((OUT/'sudoku.json').read_text());highs=json.loads((OUT/'sudoku-highs.json').read_text())
 for name in ['sudoku-easy','sudoku-hard']:
  for runtime in ['native-1','native-8','wasm']:
   off=next(r for r in sudoku if r['name']==name and r['runtime']==runtime and not r['presolve']);on=next(r for r in sudoku if r['name']==name and r['runtime']==runtime and r['presolve']);lines.append(f"| {name} | {runtime} | {off['medianMs']:.3f} | {on['medianMs']:.3f} | {off['medianMs']/on['medianMs']:.0f}× | {next(x for x in highs if x['name']==name and x['runtime']==('wasm' if runtime=='wasm' else 'native-8'))['medianMs']:.3f} |")
 lines+=['','Both Sudoku fixtures are fixed completely, have exact objective/bound zero, and use zero LP iterations and zero search nodes.','', '## Certified objectives and bounds','','| Fixture | Sense | Best feasible objective | Best bound | Gap | Result | Bound source |','|---|---|---:|---:|---:|---|---|']
 for r in records:lines.append(f"| {pathlib.Path(r['file']).name} | {r['sense']} | {num(r['objective'])} | {num(r['bound'])} | {num(r['absoluteGap'])} | {r['status']} | {r['boundSource'] or '—'} |")
 lines+=['','## Limits and corrections','','Optio still lacks full MIP presolve, cuts, and warm-started node LPs. Stronger reference proofs do not imply that Optio itself proved those cases. Semi-continuous and semi-integer domains remain unsupported by Optio; their transformed Optio results are excluded from proof and bound aggregation. Native HiGHS solves their original domains. `2122` and `life_goe` are feasible and have native optimality proofs; earlier notes calling them infeasible were incorrect. The real export is now named `planning-export` because it has an independently checked native HiGHS incumbent. The replacement `planning-infeasible` is derived from planning-s with six capacities of one: mandatory unit-0 load 1,962 exceeds combined capacity six, so its LP relaxation is infeasible.','', 'The rebuilt WASM binary is 150,941 raw bytes / 58,514 Brotli quality-11 bytes (node and web artifacts match). The working tree contained substantial solver changes before this task. Build hashes are in `build.json`; complete per-solver results and independent residual checks are in `results.json` and `scip.json`. `bounds.json` and `harness/fixtures/certified-bounds.json` provide the corrected baselines tied to SHA-256 hashes of the exact LP files.','', 'Optio itself reports 43 optimal fixtures and the five infeasible/unbounded outcomes; the 49-optimum count aggregates native solver proofs. Validation: 34 active Rust tests passed, two pre-existing tests ignored. Native and WASM Sudoku A/B checks pass; the rebuilt WASM also passes all 44 seeded/classic regressions.','', 'Reproduce:','','```sh','cargo build --release -p optio-bench --features parallel','/tmp/optio-oracle-venv/bin/python harness/tools/optimality-bench.py --time 120 --threads 8 --models-out /tmp/optio-certification-models','/tmp/optio-oracle-venv/bin/python harness/tools/certify-remaining.py --time 120 --threads 8','./crates/wasm/build.sh','node harness/tools/sudoku-presolve-bench.mjs','/tmp/optio-oracle-venv/bin/python harness/tools/sudoku-highs-bench.py','node harness/tools/sudoku-highs-bench.mjs','/tmp/optio-oracle-venv/bin/python harness/tools/optimality-report.py','```','']
 (OUT/'README.md').write_text('\n'.join(lines));print(counts)
 # A compact interactive comparison for the thread and a durable local artifact.
 payload=json.dumps(records).replace('</','<\\/')
 rows=''.join(f'<tr><td>{name}</td><td>{runtime}</td><td>{next(x for x in sudoku if x["name"]==name and x["runtime"]==runtime and not x["presolve"])["medianMs"]:.2f}</td><td>{next(x for x in sudoku if x["name"]==name and x["runtime"]==runtime and x["presolve"])["medianMs"]:.3f}</td><td>{next(x for x in highs if x["name"]==name and x["runtime"]==runtime)["medianMs"]:.3f}</td></tr>' for name in ['sudoku-easy','sudoku-hard'] for runtime in ['native-8','wasm'])
 page='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{margin:0;color:var(--foreground,#202124);font:14px var(--font-sans,system-ui)}h2{font-size:17px;margin:24px 0 12px}p{color:var(--muted-foreground,#667);line-height:1.5}table{border-collapse:collapse;width:100%;font-variant-numeric:tabular-nums}th,td{padding:10px 8px;text-align:right;border-bottom:1px solid var(--border,#ddd)}th:first-child,td:first-child{text-align:left}th{font-weight:500;color:var(--muted-foreground,#667)}.metrics{display:flex;gap:24px;flex-wrap:wrap}.metrics b{font-size:25px;display:block}.wrap{overflow:auto}select{font:inherit;background:var(--background,transparent);color:inherit;border:1px solid var(--border,#ddd);border-radius:6px;padding:6px}label{display:flex;justify-content:space-between;align-items:center;margin:22px 0 8px}.ok{color:var(--success,#287a43)}.open{color:var(--warning,#996b12)}</style></head><body>'''
 page+=f'<div class="metrics"><div><b>{len(records)}</b>Problems attempted</div><div><b>{counts["Optimal"]}</b>Proven optimal</div><div><b>{counts["Infeasible"]+counts["Unbounded"]}</b>Infeasible / unbounded</div><div><b>{counts["Open"]}</b>Open gaps</div></div><p>120 seconds per solver · 8 native workers · independently checked solutions</p><h2>Sudoku solve time (ms)</h2><div class="wrap"><table><thead><tr><th>Problem</th><th>Runtime</th><th>Presolve off</th><th>Presolve on</th><th>HiGHS</th></tr></thead><tbody>{rows}</tbody></table></div><p>Both Sudoku solutions: objective = lower bound = 0; no LP iterations or search nodes.</p>'
 page+='''<label>Objective and proof bound<select id="filter" aria-label="Filter problems"><option value="Open">Open gaps</option><option value="all">All problems</option><option value="Optimal">Optimal</option><option value="Infeasible">Infeasible</option><option value="Unbounded">Unbounded</option></select></label><div class="wrap"><table><thead><tr><th>Problem</th><th>Objective</th><th>Bound</th><th>Gap</th><th>Result</th><th>Bound source</th></tr></thead><tbody id="rows"></tbody></table></div><p>Minimization: lower bound. Maximization: upper bound. Numerical solver proofs; Optio, native HiGHS, and SCIP concurrent portfolio.</p><script>const data=PAYLOAD;const f=document.getElementById('filter');const n=v=>v==null?'—':v.toLocaleString(undefined,{maximumFractionDigits:3});function draw(){const body=document.getElementById('rows');body.replaceChildren();for(const r of data.filter(r=>f.value==='all'||r.status===f.value)){const tr=document.createElement('tr');for(const [i,v]of[r.file.split('/').pop(),n(r.objective),n(r.bound),r.relativeGap==null?'—':(100*r.relativeGap).toFixed(2)+'%',r.status,r.boundSource??'—'].entries()){const td=document.createElement('td');td.textContent=v;if(i===4)td.className=r.status==='Optimal'?'ok':'open';tr.append(td)}body.append(tr)}if(!body.children.length){const tr=document.createElement('tr');const td=document.createElement('td');td.colSpan=6;td.textContent='No problems in this group';tr.append(td);body.append(tr)}}f.addEventListener('change',draw);draw();</script></body></html>'''.replace('PAYLOAD',payload)
 (OUT/'comparison.html').write_text(page)
if __name__=='__main__':main()
